CREATE TABLE IF NOT EXISTS fin_accounts (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id INT UNSIGNED NOT NULL, code VARCHAR(40) NOT NULL, name VARCHAR(160) NOT NULL, account_type ENUM('CASH','BANK') NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'IDR', active TINYINT(1) NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_fin_account_branch_code(branch_id,code), KEY ix_fin_account_branch_active(branch_id,active), CONSTRAINT fk_fin_account_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS fin_expense_categories (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL
);
CREATE TABLE IF NOT EXISTS fin_invoices (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id INT UNSIGNED NOT NULL, customer_id INT UNSIGNED NOT NULL, internal_ref VARCHAR(50) NOT NULL UNIQUE, official_number VARCHAR(50) NULL UNIQUE, status ENUM('DRAFT','SUBMITTED','RETURNED','APPROVED','ISSUED','PARTIALLY_PAID','PAID','VOID') NOT NULL DEFAULT 'DRAFT', invoice_date DATE NOT NULL, due_date DATE NULL, subtotal DECIMAL(18,2) NOT NULL DEFAULT 0, tax_amount DECIMAL(18,2) NOT NULL DEFAULT 0, discount_amount DECIMAL(18,2) NOT NULL DEFAULT 0, total_amount DECIMAL(18,2) NOT NULL DEFAULT 0, version INT UNSIGNED NOT NULL DEFAULT 1, created_by INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY ix_fin_invoice_scope(branch_id,status,invoice_date), CONSTRAINT fk_fin_invoice_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE RESTRICT, CONSTRAINT fk_fin_invoice_customer FOREIGN KEY(customer_id) REFERENCES md_customers(id) ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS fin_invoice_lines (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id INT UNSIGNED NOT NULL, description VARCHAR(255) NOT NULL, quantity DECIMAL(18,3) NOT NULL DEFAULT 1, unit_price DECIMAL(18,2) NOT NULL DEFAULT 0, line_total DECIMAL(18,2) NOT NULL DEFAULT 0, source_type VARCHAR(40) NULL, source_id INT UNSIGNED NULL, created_at DATETIME NOT NULL, KEY ix_fin_line_invoice(invoice_id), CONSTRAINT fk_fin_line_invoice FOREIGN KEY(invoice_id) REFERENCES fin_invoices(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS fin_payments (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id INT UNSIGNED NOT NULL, payment_ref VARCHAR(50) NOT NULL UNIQUE, payment_date DATE NOT NULL, account_id INT UNSIGNED NOT NULL, amount DECIMAL(18,2) NOT NULL, status ENUM('DRAFT','POSTED','REVERSED') NOT NULL DEFAULT 'DRAFT', note VARCHAR(255) NULL, version INT UNSIGNED NOT NULL DEFAULT 1, created_by INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY ix_fin_payment_scope(branch_id,payment_date,status), CONSTRAINT fk_fin_payment_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE RESTRICT, CONSTRAINT fk_fin_payment_account FOREIGN KEY(account_id) REFERENCES fin_accounts(id) ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS fin_payment_allocations (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_id INT UNSIGNED NOT NULL, invoice_id INT UNSIGNED NOT NULL, amount DECIMAL(18,2) NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY uq_fin_allocation(payment_id,invoice_id), CONSTRAINT fk_fin_alloc_payment FOREIGN KEY(payment_id) REFERENCES fin_payments(id) ON DELETE RESTRICT, CONSTRAINT fk_fin_alloc_invoice FOREIGN KEY(invoice_id) REFERENCES fin_invoices(id) ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS fin_supplier_bills (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id INT UNSIGNED NOT NULL, supplier_id INT UNSIGNED NOT NULL, bill_ref VARCHAR(80) NOT NULL, bill_date DATE NOT NULL, due_date DATE NULL, status ENUM('DRAFT','SUBMITTED','VERIFIED','PARTIALLY_PAID','PAID','VOID') NOT NULL DEFAULT 'DRAFT', subtotal DECIMAL(18,2) NOT NULL DEFAULT 0, total_amount DECIMAL(18,2) NOT NULL DEFAULT 0, version INT UNSIGNED NOT NULL DEFAULT 1, created_by INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_fin_bill_branch_ref(branch_id,bill_ref), KEY ix_fin_bill_scope(branch_id,status,due_date), CONSTRAINT fk_fin_bill_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE RESTRICT, CONSTRAINT fk_fin_bill_supplier FOREIGN KEY(supplier_id) REFERENCES md_suppliers(id) ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS fin_supplier_bill_lines (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, bill_id INT UNSIGNED NOT NULL, description VARCHAR(255) NOT NULL, quantity DECIMAL(18,3) NOT NULL DEFAULT 1, unit_price DECIMAL(18,2) NOT NULL DEFAULT 0, line_total DECIMAL(18,2) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, CONSTRAINT fk_fin_bill_line_bill FOREIGN KEY(bill_id) REFERENCES fin_supplier_bills(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS fin_cash_ledger (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id INT UNSIGNED NOT NULL, account_id INT UNSIGNED NOT NULL, transaction_type ENUM('OPENING','RECEIPT','PAYMENT','EXPENSE','TRANSFER_IN','TRANSFER_OUT','REVERSAL') NOT NULL, reference_type VARCHAR(40) NULL, reference_id INT UNSIGNED NULL, transaction_date DATE NOT NULL, debit DECIMAL(18,2) NOT NULL DEFAULT 0, credit DECIMAL(18,2) NOT NULL DEFAULT 0, note VARCHAR(255) NULL, created_by INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, KEY ix_fin_cash_scope(account_id,transaction_date), CONSTRAINT fk_fin_cash_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE RESTRICT, CONSTRAINT fk_fin_cash_account FOREIGN KEY(account_id) REFERENCES fin_accounts(id) ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS fin_expenses (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id INT UNSIGNED NOT NULL, category_id INT UNSIGNED NOT NULL, account_id INT UNSIGNED NOT NULL, expense_date DATE NOT NULL, amount DECIMAL(18,2) NOT NULL, status ENUM('DRAFT','SUBMITTED','APPROVED','POSTED','REJECTED','VOID') NOT NULL DEFAULT 'DRAFT', description VARCHAR(255) NOT NULL, version INT UNSIGNED NOT NULL DEFAULT 1, created_by INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY ix_fin_expense_scope(branch_id,status,expense_date), CONSTRAINT fk_fin_expense_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE RESTRICT, CONSTRAINT fk_fin_expense_category FOREIGN KEY(category_id) REFERENCES fin_expense_categories(id) ON DELETE RESTRICT, CONSTRAINT fk_fin_expense_account FOREIGN KEY(account_id) REFERENCES fin_accounts(id) ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS fin_events (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, entity_type VARCHAR(40) NOT NULL, entity_id INT UNSIGNED NOT NULL, previous_state VARCHAR(30) NULL, next_state VARCHAR(30) NULL, actor_id INT UNSIGNED NOT NULL, branch_id INT UNSIGNED NOT NULL, request_key CHAR(64) NOT NULL, detail JSON NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY uq_fin_event_request(request_key), KEY ix_fin_event_entity(entity_type,entity_id), CONSTRAINT fk_fin_event_actor FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT, CONSTRAINT fk_fin_event_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE RESTRICT);

INSERT IGNORE INTO permissions(code,name) VALUES ('finance.account.view','Lihat rekening kas dan bank'); INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code='finance.account.view' WHERE r.name='Finance';
